def pan_grid(w=302, d=282, h=18, pitch=158, bar=4, finger=39):
    solids = []
    for x in [-pitch/2, pitch/2]:
        rim = s3d.extrude("support_frame", s3d.rect(w=w-pitch, d=d, r=10), h=bar)
        rim = s3d.pocket(rim, s3d.rect(w=w-pitch-2*bar, d=d-2*bar, r=7), on=rim.face("top"))
        rim = s3d.at(rim, x=x)
        solids.append(rim)
        for y in [-d/4, 0, d/4]:
            rail = s3d.at(s3d.box("crossbar", w=w-pitch, d=bar, h=bar), x=x, y=y, z=h-bar)
            solids.append(rail)
            for side in [-1, 1]:
                foot = s3d.at(s3d.box("support_leg", w=bar, d=bar, h=h), x=x+side*(w-pitch-bar)/2, y=y)
