import sand3d as s3d
import random
import math
import numpy as np

def snow_covered_spring_linden_cluster(seed=0):
    large = s3d.at(linden_tree(seed + 101, 14200, 'large'), x=-2800, y=1100, rz=-12)
    medium = s3d.at(linden_tree(seed + 211, 11400, 'medium'), x=3900, y=1300, rz=31)
    small = s3d.at(linden_tree(seed + 337, 9100, 'small'), x=0, y=-3700, rz=-24)
    return s3d.assembly('snow_covered_spring_linden_cluster', large, medium, small)

def linden_tree(seed, height, label):
    data = linden_growth(seed + 1, height)
    if label == 'large':
        trunk = large_linden_trunk_roots(seed + 2, height)
        wood = large_linden_branchwork(seed + 3, data)
        leaves, supports = large_linden_spring_leaves(seed + 4, data)
        snow = large_linden_snow(seed + 5, data, supports)
    elif label == 'medium':
        trunk = medium_linden_trunk_roots(seed + 2, height)
        wood = medium_linden_branchwork(seed + 3, data)
        leaves, supports = medium_linden_spring_leaves(seed + 4, data)
        snow = medium_linden_snow(seed + 5, data, supports)
    else:
        trunk = small_linden_trunk_roots(seed + 2, height)
        wood = small_linden_branchwork(seed + 3, data)
        leaves, supports = small_linden_spring_leaves(seed + 4, data)
        snow = small_linden_snow(seed + 5, data, supports)
    return s3d.group(label + '_linden', trunk, wood, leaves, snow)

def linden_growth(seed, h, count=11, stem_band=(0.28, 0.42), crown=(0.23, 0.14, 0.08), rise_band=(0.29, 0.06), lean=(-0.03, 0.01), limb_taper=(0.02, 0.01)):
    rng = random.Random(seed)
    branches = []
    with s3d.facets(7, smooth=True):
        for i, f in enumerate(s3d.ring(count, 1).jitter(rz=18, seed=seed + 1)):
            radial = np.array([f.origin.x, f.origin.y, 0])
            side = np.array([-f.origin.y, f.origin.x, 0])
            t = i / (count - 1)
            z = h * (stem_band[0] + stem_band[1] * t)
            base = np.array([lean[0] * z, lean[1] * z, z])
            radius = h * (crown[0] + crown[1] * 4 * t * (1 - t) - crown[2] * t) * rng.uniform(0.87, 1.12)
            rise = h * (rise_band[0] - rise_band[1] * t) * rng.uniform(0.88, 1.14)
            bend = side * radius * rng.uniform(-0.18, 0.18)
            progression = [(0, 0), (0.24, 0.43), (0.63, 0.78), (1, 1)]
            points = [tuple(base + radial * radius * u + bend * u * u + np.array([0, 0, rise * v])) for u, v in progression]
            path = s3d.spline(points)
            diameter = h * (limb_taper[0] - limb_taper[1] * t) * rng.uniform(0.8, 1.1)
            branches.append((path, diameter, 0))
            branches.extend(lateral_growth(seed + 100 + i, h, path, diameter, radial, side, t))
    return branches

def lateral_growth(seed, h, path, diameter, radial, side, t):
    rng = random.Random(seed)
    branches = []
    for j, site in enumerate(s3d.along(path, count=3, span=(0.4, 0.91))):
        p = np.array(tuple(site.origin))
        sign = 1 if j % 2 else -1
        direction = radial * 0.58 + side * sign * 0.81
        length = h * rng.uniform(0.08, 0.12) * (1 - 0.22 * t)
        dz = length * rng.uniform(0.3, 0.65)
        end = p + direction * length + np.array([0, 0, dz])
        mid = p + direction * length * 0.47 + np.array([0, 0, dz * 0.72])
        subpath = s3d.spline([tuple(p), tuple(mid), tuple(end)])
        subd = diameter * (0.31 - 0.04 * j)
        branches.append((subpath, subd, 1))
        branches.extend(terminal_growth(seed + 10 + j, h, subpath, subd, direction, radial, side))
    return branches

def terminal_growth(seed, h, path, d, direction, radial, side):
    rng = random.Random(seed)
    branches = []
    for k, site in enumerate(s3d.along(path, count=3, span=(0.4, 0.96))):
        q = np.array(tuple(site.origin))
        out = direction * 0.62 + radial * 0.34 + side * ((-1 if k % 2 else 1) * 0.4)
        reach = h * rng.uniform(0.04, 0.07)
        up = reach * rng.uniform(0.25, 0.62)
        twig = s3d.spline([tuple(q), tuple(q + out * reach * 0.5 + np.array([0, 0, up * 0.65])), tuple(q + out * reach + np.array([0, 0, up]))])
        branches.append((twig, d * 0.3, 2))
    return branches

def large_linden_trunk_roots(seed, h):
    return trunk_roots(seed, h)

def trunk_roots(seed, h, base_ratio=0.059, root_ratio=0.115):
    rng = random.Random(seed)
    d = h * base_ratio
    with s3d.facets(18, smooth=True):
        girths = [(0, 1.5), (0.03, 1), (0.1, 0.77), (0.31, 0.6), (0.55, 0.4), (0.77, 0.23), (0.88, 0.05), (0.93, 0)]
        trunk = s3d.loft('flared_ridged_trunk', *[s3d.station(z * h, d * w, d * w * 0.94, x=-z * h * 0.03, y=z * h * 0.01) for z, w in girths])
        s3d.displace(trunk, d * 0.018, d * 0.35, noise=lambda x, y, z: np.cos(np.arctan2(y, x) * 14 + np.sin(z / 900)), direction='radial', step=d * 0.5)
    s3d.material(trunk, 'bark', color=bark_colour, roughness=0.91)
    roots = []
    with s3d.facets(9, smooth=True):
        for f in s3d.ring(7, 1).jitter(rz=16, seed=seed + 1):
            x, y = (f.origin.x, f.origin.y)
            length = h * root_ratio * rng.uniform(0.72, 1.12)
            width = d * rng.uniform(0.3, 0.48)
            path = s3d.spline([(x * d * 0.2, y * d * 0.2, width * 0.63), (x * length * 0.43, y * length * 0.43, width * 0.34), (x * length, y * length, 0)])
            root = s3d.wire('exposed_root_buttress', path, [(0, width), (0.5, width * 0.53), (1, 0)])
            s3d.material(root, 'bark', color=bark_colour, roughness=0.94)
            roots.append(root)
    return s3d.group('trunk_and_root_flare', trunk, roots)

def bark_colour(x, y, z):
    a = np.arctan2(y, x)
    ridges = 0.5 + 0.5 * np.sin(a * 17 + np.sin(z / 780) * 0.5)
    broad = s3d.noise(x / 300, y / 300, z / 1300, seed=63)
    v = 0.31 + 0.075 * ridges + 0.04 * broad
    return np.stack((v * 1.08, v * 1.01, v * 0.9), axis=-1)

def large_linden_branchwork(seed, data):
    return branchwork(seed, data)

def branchwork(seed, data):
    wood = []
    rng = random.Random(seed)
    for path, d, level in data:
        with s3d.facets(9 if level == 0 else 6, smooth=True):
            branch = s3d.wire('ascending_limb' if level == 0 else 'spreading_twig', path, [(0, d), (0.38, d * 0.69), (0.76, d * 0.32), (1, max(3, d * 0.045))])
        s3d.material(branch, 'bark', color=rng.choice(['#615b4b', '#696357', '#70695c']), roughness=0.88)
        wood.append(branch)
    return s3d.merge(*wood)

def large_linden_spring_leaves(seed, data):
    return spring_leaves(seed, data)

def spring_leaves(seed, data, leaf_length=320):
    rng = random.Random(seed)
    leaves = []
    supports = []
    prototype = heart_leaf(leaf_length, leaf_length * 0.91)
    palette = ['#91b644', '#85aa38', '#a6bf55', '#7e9f39']
    for i, (path, d, level) in enumerate(data):
        if level != 2:
            continue
        sites = s3d.along(path, count=6, span=(0.22, 1))
        for j, site in enumerate(sites):
            p = site.origin
            angle = rng.uniform(-180, 180)
            tilt = rng.uniform(-26, 32)
            size = rng.uniform(0.72, 1.19)
            frame = s3d.Frame((p.x, p.y, p.z)).turn(rx=tilt, ry=rng.uniform(-25, 25), rz=angle)
            leaf = s3d.at(s3d.copy(prototype), on=frame, scale=size)
            s3d.material(leaf, 'leaf', color=palette[(i + j) % len(palette)], roughness=0.4)
            leaves.append(leaf)
            if j in (2, 4) and rng.random() < 0.75:
                supports.append((frame, leaf_length * size))
    s3d.delete(prototype)
    return (s3d.merge(*leaves), supports)

def heart_leaf(length=180, width=153, thickness=1.0):
    half = [(0, 0.14), (-0.28, 0), (-0.49, 0.19), (-0.42, 0.31), (-0.46, 0.43), (-0.27, 0.66), (0, 1)]
    outline = half + [(-x * 0.94, y) for x, y in reversed(half[1:-1])]
    blade = s3d.extrude('serrated_cordate_leaf', s3d.poly([(x * width, y * length) for x, y in outline]), thickness)
    s3d.material(blade, 'leaf', color='#a6bd40', roughness=0.4)
    return blade

def large_linden_snow(seed, data, supports):
    return snow_cover(seed, data, supports)

def snow_cover(seed, data, supports):
    rng = random.Random(seed)
    snow = []
    with s3d.facets(5, smooth=True):
        for path, d, level in data:
            if rng.random() > (0.9 if level == 0 else 0.54):
                continue
            start = rng.uniform(0.12, 0.34)
            end = rng.uniform(0.72, 0.96)
            sites = s3d.along(path, count=3, span=(start, end))
            pts = []
            for k, site in enumerate(sites):
                p = site.origin
                u = start + (end - start) * k / (len(sites) - 1)
                radius = d * (1 - u) * 0.5
                pts.append((p.x, p.y, p.z + radius + 13))
            path2 = s3d.spline(pts)
            width = max(180, d * 1.65)
            cap = s3d.wire('snow_on_upper_branch', path2, (width, max(120, width * 0.6)))
            s3d.material(cap, 'snow', color='#dce6ec', roughness=0.96)
            snow.append(cap)
    with s3d.facets(6, smooth=True):
        for frame, leaf_length in supports:
            length = leaf_length * 1.45
            cap = s3d.loft('snow_on_leaf', s3d.station(0, length * 0.64, length * 0.65, y=length * 0.48), s3d.station(length * 0.1, length * 0.78, length * 0.72, y=length * 0.48), s3d.station(length * 0.23, length * 0.57, length * 0.55, x=length * 0.04, y=length * 0.49), s3d.station(length * 0.36, 0, 0, x=length * 0.08, y=length * 0.51))
            s3d.material(cap, 'snow', color='#e1e9ed', roughness=0.98)
            snow.append(s3d.at(cap, on=frame.offset(1)))
    return s3d.merge(*snow)

def medium_linden_trunk_roots(seed, h):
    return trunk_roots(seed, h)

def medium_linden_branchwork(seed, data):
    return branchwork(seed, data)

def medium_linden_spring_leaves(seed, data):
    return spring_leaves(seed, data)

def medium_linden_snow(seed, data, supports):
    return snow_cover(seed, data, supports)

def small_linden_trunk_roots(seed, h):
    return trunk_roots(seed, h)

def small_linden_branchwork(seed, data):
    return branchwork(seed, data)

def small_linden_spring_leaves(seed, data):
    return spring_leaves(seed, data)

def small_linden_snow(seed, data, supports):
    return snow_cover(seed, data, supports)

import sand3d as s3d
import numpy as np


