    left = s3d.at(left_boulder(seed=seed + 23), x=-3350, y=250, rz=-19)
    right = s3d.at(right_boulder(seed=seed + 37), x=3200, y=850, rz=17)
    front = s3d.at(front_center_boulder(seed=seed + 43), x=-300, y=-2550, rz=-12)
    rear = s3d.at(rear_boulder(seed=seed + 59), x=-500, y=3300, rz=28)
    rear_left = s3d.at(rear_left_boulder(seed=seed + 67), x=-3300, y=2700, rz=-13)
    front_left = s3d.at(front_left_boulder(seed=seed + 79), x=-3550, y=-2350, rz=-15)
    front_right = s3d.at(front_right_boulder(seed=seed + 89), x=3300, y=-2200, rz=21)
