def central_boulder(seed=0):
    return weathered_stone('central_boulder', 4800, 4200, 3400, seed, shoulder=2.5, lean=0.07, seam=1)


def weathered_stone(name, w, d, h, seed, shoulder=2.3, lean=0.06, seam=0, cell=150):
    base = cell * 1.5
    density, seam_distance, broken_seam = worn_stone_density(w, d, h, base, cell, shoulder, lean, seam, seed=seed + 1)
    stone = s3d.field(name + '_mass', (w * 1.25, d * 1.25, h + base + cell * 3), density, cell=cell)
    stone_colour = stone_palette(base, h, seam, seam_distance, broken_seam, seed=seed + 101)
    s3d.material(stone, 'rock', color=stone_colour, roughness=0.89)
    s3d.smooth(stone, angle=85)
    stone = s3d.at(stone, z=-base)
    return s3d.group(name, stone)


def worn_stone_density(w, d, h, base, cell, shoulder, lean, seam, seed=0, outline=0.19, erosion=0.014, grain=0.003, seam_depth=0.025, seam_width=95, seam_wander=200):
    rng = np.random.default_rng(seed)
    # Rounded fracture shoulder and taper vary independently for every stone.
    slant, taper = rng.uniform(-0.6, 0.6, 2)
    def seam_distance(x, y, z):
        waviness = s3d.noise(x / w, y / d, z / h, seed=seed + 4)
        return x + y * slant - (z - base) * 0.4 + w * 0.12 + seam_wander * waviness
    def broken_seam(x, y, z):
        scale = cell * 7
        return np.clip(s3d.noise(x / scale, y / scale, z / scale, seed=seed + 5) + 0.35, 0, 1)
    def density(x, y, z):
        # Section centre is below mid-height, leaving a broad, naturally truncated foot.
        # Broad noise changes the outline; the two smaller scales are actual worn relief.
        height = (z - base) / h
        section = 1 + taper * (height - 0.5) * 0.4
        xx = (x - w * lean * height) / (w / 2 * section)
        yy = (y + d * lean * height * 0.5) / (d / 2)
        zz = (height - 0.37) / 0.63
        rounded = (np.abs(xx) ** shoulder + np.abs(yy) ** shoulder + np.abs(zz) ** shoulder) ** (1 / shoulder) - 1
        broad = s3d.noise(x / (w * 0.42), y / (d * 0.42), z / (h * 0.55), seed=seed + 1)
        wear_scale, grit_scale = cell * 4, cell
        wear = s3d.noise(x / wear_scale, y / wear_scale, z / wear_scale, seed=seed + 2)
        grit = s3d.noise(x / grit_scale, y / grit_scale, z / grit_scale, seed=seed + 3)
        sd = seam_distance(x, y, z)
        groove = seam * seam_depth * np.exp(-(sd / seam_width) ** 2) * broken_seam(x, y, z)
        return np.maximum(rounded + outline * broad + erosion * wear + grain * grit + groove, (base - z) / h)
    return density, seam_distance, broken_seam


def stone_palette(base, h, seam, seam_distance, broken_seam, seed=0, patch_scale=1450, grain_scale=155, seam_width=95):
    rng = np.random.default_rng(seed)
    stone_tone = rng.uniform(-0.025, 0.025)
    # Authored weathered granite palette: neutral gray, weak warm oxidation,
    # smaller mineral clouds and fine light/dark grains, never baked lighting.
    neutral = np.array([0.43, 0.43, 0.41]) + stone_tone
    warm_tint = np.array([0.05, 0.01, -0.03])
    mineral_gain, grain_gain, cloud_gain = 0.035, 0.04, 0.02
    oxidation_gain, oxidation_limit = 1.6, 0.65
    foot_depth, foot_fraction, seam_tint = 0.04, 0.3, 0.11
    def stone_colour(x, y, z):
        broad = s3d.noise(x / patch_scale, y / patch_scale, z / patch_scale, seed=seed + 6)
        mineral_scale = patch_scale / 3
        mineral = s3d.noise(x / mineral_scale, y / mineral_scale, z / mineral_scale, seed=seed + 7)
        speckle = s3d.noise(x / grain_scale, y / grain_scale, z / grain_scale, seed=seed + 8)
        warm = np.clip(broad * oxidation_gain, 0, oxidation_limit)
        value = mineral * mineral_gain + speckle * grain_gain + broad * cloud_gain
        foot = np.clip(1 - (z - base) / (h * foot_fraction), 0, 1) * foot_depth
        sd = seam_distance(x, y, z)
        line = seam * np.exp(-(sd / seam_width) ** 2) * broken_seam(x, y, z) * seam_tint
        rgb = neutral + (value - foot - line)[..., None] + warm[..., None] * warm_tint
        return np.clip(rgb, 0, 1)
    return stone_colour


